script:
frappe.listview_settings["Notification"] = {
  formatters: {
    subject(value) {
      if (!value) return "";
      return frappe.utils.escape_html(
        value
          .replace(/\{\{\s*_\(\s*(['"])(.*?)\1\s*\)[^}]*\}\}/g, "$2")
          .replace(/\{\{\s*([^}]*?)\s*\}\}/g, (m, e) => "<" + e.split(".").pop().trim() + ">")
          .replace(/\{%.*?%\}/g, "")
          .replace(/\{\d*\}/g, "…")
          .replace(/\s+/g, " ")
          .trim()
      );
    },
  },
};
